* { box-sizing: border-box; }
:root { color-scheme: dark; font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif; background: #142b35; color: #f4f1e8; }
body { min-height: 100vh; margin: 0; padding: 32px 16px; display: grid; place-content: center; background: radial-gradient(ellipse at 50% 10%, #254955, #142b35 70%); }
.board-card { width: min(760px, 100%); padding: 30px; border: 1px solid #47616a; border-radius: 18px; background: #1b343e; box-shadow: 0 24px 70px #08171d88; }
.board-header { display: flex; align-items: center; justify-content: space-between; gap: 20px; }
.eyebrow, .clock-label { margin: 0; color: #a8c0bc; font-size: 14px; font-weight: 700; letter-spacing: .12em; }
h1 { margin: 6px 0 0; font-size: clamp(30px, 6vw, 42px); line-height: 1.1; letter-spacing: -.04em; }
.clock-panel { text-align: right; padding: 12px 16px; border: 1px solid #47616a; border-radius: 10px; background: #142b35; }
.clock-panel time { display: block; margin-top: 3px; color: #f4c95d; font-size: 28px; font-weight: 800; font-variant-numeric: tabular-nums; }
.board-note { display: flex; align-items: center; gap: 9px; margin: 28px 0 12px; color: #bbcbc6; font-size: 15px; }
.status-dot { width: 9px; height: 9px; border-radius: 50%; background: #83c79d; box-shadow: 0 0 10px #83c79d88; }
.table-wrap { overflow-x: auto; }
table { width: 100%; border-collapse: collapse; text-align: left; }
th { padding: 13px 12px; color: #a8c0bc; font-size: 13px; letter-spacing: .08em; text-transform: uppercase; }
td { padding: 17px 12px; border-top: 1px solid #354d55; font-size: 17px; }
td:first-child { width: 95px; font-variant-numeric: tabular-nums; font-weight: 750; }
td:last-child { width: 90px; }
.train-row { transition: background-color .18s, color .18s; }
.train-row.next { background: #f4c95d1c; box-shadow: inset 4px 0 #f4c95d; }
.train-row.next td:first-child { color: #f4c95d; }
.train-row.departed { color: #829397; }
.train-row.departed .status { color: #829397; }
.status { color: #83c79d; font-size: 14px; font-weight: 700; }
.board-footer { display: flex; align-items: center; justify-content: space-between; gap: 16px; margin-top: 22px; padding-top: 20px; border-top: 1px solid #354d55; }
.board-footer p { margin: 0; color: #f4c95d; font-size: 16px; font-weight: 650; }
button { flex: 0 0 auto; min-height: 48px; padding: 0 18px; border: 0; border-radius: 9px; background: #f4c95d; color: #142b35; font: inherit; font-size: 16px; font-weight: 800; cursor: pointer; transition: transform .12s, background-color .12s, box-shadow .12s; }
button:hover { background: #ffda78; box-shadow: 0 5px 18px #f4c95d33; }
button:active { transform: translateY(2px) scale(.98); }
button:focus-visible { outline: 3px solid #f4f1e8; outline-offset: 4px; }
.hint { margin: 20px 0 0; color: #a8c0bc; text-align: center; font-size: 15px; }
.visually-hidden { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip: rect(0, 0, 0, 0); white-space: nowrap; border: 0; }
@media (max-width: 520px) {
  body { padding: 20px 12px; }
  .board-card { padding: 22px 16px; }
  th, td { padding-right: 7px; padding-left: 7px; }
  th { font-size: 12px; }
  td { font-size: 15px; }
  td:first-child { width: 64px; }
  td:last-child { width: 70px; }
  .status { font-size: 12px; }
  .board-footer { align-items: stretch; flex-direction: column; }
  button { width: 100%; }
}

const trains = [
  { time: "08:10", destination: "Portland", platform: "2" },
  { time: "08:25", destination: "Lakewood", platform: "4" },
  { time: "08:40", destination: "Fairview", platform: "1" },
  { time: "09:00", destination: "Riverside", platform: "3" },
  { time: "09:20", destination: "Summit", platform: "2" },
  { time: "09:45", destination: "Harbor Point", platform: "5" }
];
let minutes = 8 * 60;
const clock = document.querySelector("#clock");
const departures = document.querySelector("#departures");
const announcement = document.querySelector("#announcement");
const advanceButton = document.querySelector("#advance");

function render() {
  const now = minutes % (24 * 60);
  const format = value => `${String(Math.floor(value / 60)).padStart(2, "0")}:${String(value % 60).padStart(2, "0")}`;
  clock.textContent = format(now);
  const nextIndex = trains.findIndex(train => {
    const [hour, minute] = train.time.split(":").map(Number);
    return hour * 60 + minute > now;
  });
  departures.replaceChildren(...trains.map((train, index) => {
    const [hour, minute] = train.time.split(":").map(Number);
    const departed = hour * 60 + minute <= now;
    const row = document.createElement("tr");
    row.className = `train-row${departed ? " departed" : ""}${index === nextIndex ? " next" : ""}`;
    if (index === nextIndex) row.setAttribute("aria-current", "true");
    const values = [train.time, train.destination, train.platform, departed ? "Departed" : index === nextIndex ? "Next train" : "On time"];
    values.forEach((value, cellIndex) => {
      const cell = document.createElement("td");
      cell.textContent = value;
      if (cellIndex === 3) cell.className = "status";
      row.append(cell);
    });
    return row;
  }));
  announcement.textContent = nextIndex === -1
    ? "No more departures today"
    : `Next departure: ${trains[nextIndex].destination} at ${trains[nextIndex].time}`;
}

advanceButton.addEventListener("click", () => {
  minutes += 5;
  render();
});
render();
